begin;
do $$
declare o uuid;c uuid;p uuid;j uuid;j2 uuid;s1 uuid:=gen_random_uuid();s2 uuid:=gen_random_uuid();city uuid;m uuid;result jsonb;
begin
 select id into city from public.cities limit 1;
 insert into public.users(clerk_user_id,role,onboarding_completed_at) values('resolution-owner','owner',now()) returning id into o;
 insert into public.users(clerk_user_id,role,onboarding_completed_at) values('resolution-cleaner','cleaner',now()) returning id into c;
 insert into public.properties(city_id,name,address,cleaning_config) values(city,'Resolution fixture','Local only',jsonb_build_object('rooms','[]'::jsonb,'supplies',jsonb_build_array(jsonb_build_object('id',s1,'name','Soap'),jsonb_build_object('id',s2,'name','Paper')))) returning id into p;
 insert into public.property_owners values(p,o);
 insert into public.jobs(property_id,checkout_date,start_at,end_at,timezone_snapshot,solo_rate_cents_snapshot) values(p,current_date,(current_date+time '11:00') at time zone 'America/Detroit',(current_date+time '15:00') at time zone 'America/Detroit','America/Detroit',7500) returning id into j;
 update public.jobs set started_at=now(),started_by=c where id=j;
 perform set_config('request.jwt.claims','{"sub":"resolution-owner"}',true);
 if not exists(select 1 from private.inbox_items() where id='start:'||j) then raise exception 'Start missing';end if;
 insert into public.job_supply_reports values(j,s1,'Soap','low',c,now()-interval '2 hours'),(j,s2,'Paper','empty',c,now()-interval '2 hours');
 insert into public.job_maintenance_reports values(j,'water','attention','Leak',c,now()-interval '2 hours');
 update public.jobs set status='completed',completed_at=now()-interval '1 hour',completed_by=c where id=j;
 if exists(select 1 from private.inbox_items() where id='start:'||j) then raise exception 'Completed start retained';end if;
 if private.active_report_details(j,'low_supplies')<>'Paper, Soap' then raise exception 'Initial supplies missing';end if;
 insert into private.supply_purchases(property_id,supply_id,product_name,cost_cents,purchase_date,recorded_by) values(p,s1,'Soap',100,current_date,o);
 if private.active_report_details(j,'low_supplies')<>'Paper, Soap' then raise exception 'Purchase incorrectly resolves alert';end if;
 update private.supply_purchases set restocked_date=current_date,restocked_at=now() where property_id=p;
 if private.active_report_details(j,'low_supplies')<>'Paper' then raise exception 'Partial restock failed';end if;
 if not exists(select 1 from private.inbox_items() where id='low_supplies:'||j and body not like '%Soap%') then raise exception 'Stale partial copy';end if;
 insert into public.jobs(property_id,checkout_date,start_at,end_at,timezone_snapshot,solo_rate_cents_snapshot) values(p,current_date+1,(current_date+1+time '11:00') at time zone 'America/Detroit',(current_date+1+time '15:00') at time zone 'America/Detroit','America/Detroit',7500) returning id into j2;
 insert into public.job_supply_reports values(j2,s2,'Paper','full',c,now());
 insert into public.job_maintenance_reports values(j2,'water','ok','Fixed',c,now());
 update public.jobs set status='completed',completed_at=now(),completed_by=c where id=j2;
 if private.active_report_details(j,'low_supplies') is not null or private.active_report_details(j,'maintenance') is not null then raise exception 'New reports did not resolve alerts';end if;
 if exists(select 1 from private.inbox_items() where id in ('low_supplies:'||j,'maintenance:'||j)) then raise exception 'Resolved alerts retained';end if;
 insert into private.push_preferences(user_id,low_supplies,maintenance) values(o,true,true) on conflict(user_id) do update set low_supplies=true,maintenance=true;
 insert into private.push_messages(logical_key,user_id,kind,job_ids,expires_at) values('resolution-check',o,'maintenance',array[j],now()+interval '1 hour') returning id into m;
 if private.push_content(m,now()) is not null then raise exception 'Resolved push retained';end if;
 result:=public.bloom_notification_inbox();
 if result->'items'->0->>'id'<>'completion:'||j2 then raise exception 'Not newest first: %',result;end if;
 if exists(select 1 from (select (v->>'createdAt')::timestamptz t,lag((v->>'createdAt')::timestamptz) over(order by ord) prior from jsonb_array_elements(result->'items') with ordinality a(v,ord)) q where t>prior) then raise exception 'Ordering failed';end if;
 perform set_config('request.jwt.claims','{"sub":"resolution-cleaner"}',true);
 if exists(select 1 from private.inbox_items() where id in ('completion:'||j2,'maintenance:'||j)) then raise exception 'Role boundary failed';end if;
end $$;
rollback;
